sp_widget.client_script:
api.controller = function($scope) {
  $scope.checkin = function() {
    if (!$scope.data.res) return;
    $scope.server.get({
      action: 'checkin',
      sysId:  $scope.data.res.sysId
    }).then(function(r) {
      $scope.data.res    = r.data.res;
      $scope.data.notice = r.data.notice;
    });
  };
};

sp_widget.css:
.wrm-next-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 14px 18px 16px;
}

.wrm-next-head {
  font-size: 11px;
  letter-spacing: .08em;
  color: var(--ink-3);
  margin-bottom: 10px;
}

.wrm-next-row {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  background: transparent;
  border: 0;
  padding: 0;
}

.wrm-next-row .when { flex: none; }
.wrm-next-row .when .lbl { font-size: 10px; letter-spacing: .07em; color: var(--ink-3); }
.wrm-next-row .when .tm { font-size: 15px; color: var(--ink); }

.wrm-next-row .what { flex: 1; min-width: 180px; }
.wrm-next-row .what .nm { font-size: 15px; color: var(--ink); }
.wrm-next-row .what .sub { font-size: 11px; color: var(--ink-3); }

.wrm-next-row .pill {
  font-size: 11px;
  padding: 5px 12px;
  border-radius: var(--r-pill);
  white-space: nowrap;
  flex: none;
}
.wrm-next-row .pill.free { background: var(--free-bg); color: var(--free-fg); }
.wrm-next-row .pill.held { background: var(--held-bg); color: var(--held-fg); }

.wrm-next-row .btn {
  font-size: 13px;
  font-weight: 500;
  border: 0;
  padding: 9px 20px;
  border-radius: var(--r-pill);
  background: var(--clay);
  color: var(--on-clay);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  flex: none;
}
.wrm-next-row .btn:hover {
  background: var(--clay-press);
  color: var(--on-clay);
  text-decoration: none;
}
.wrm-next-row .btn.ghost {
  background: transparent;
  color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--line);
}
.wrm-next-row .btn.ghost:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.wrm-next-notice {
  font-size: 12px;
  color: var(--held-fg);
  background: var(--held-bg);
  padding: 8px 13px;
  border-radius: var(--r-soft);
  margin-top: 8px;
}

.wrm-next-none {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: var(--ink-2);
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: var(--r-card);
  padding: 18px 20px;
}
.wrm-next-none a { color: var(--clay); }

sp_widget.script:
(function() {

  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
  var MONTHS   = ['JAN','FEB','MAR','APR','MAY','JUN',
                  'JUL','AUG','SEP','OCT','NOV','DEC'];

  var CHECKIN_LEAD_MIN = 60;
  var nowMs = new GlideDateTime().getNumericValue();

  function parts(dt) {
    if (!dt) return { month:'', day:'', time:'', weekday:'' };
    var p = dt.split(' ');
    var d = p[0].split('-');
    var js = new Date(Date.UTC(+d[0], +d[1] - 1, +d[2]));
    return {
      month:   MONTHS[+d[1] - 1],
      day:     d[2],
      time:    p[1] ? p[1].substring(0, 5) : '',
      weekday: WEEKDAYS[js.getUTCDay()]
    };
  }

  data.res = null;

  // Handle a check-in posted from the client.
  if (input && input.action === 'checkin' && input.sysId) {
    var r = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
    if (r.get(input.sysId) &&
        r.getValue('reserved_for') === gs.getUserID() &&
        r.getValue('reservation_status') === 'pending_check_in') {

      var st = r.getValue('work_start');
      var opens = st ? new GlideDateTime(st).getNumericValue() - (CHECKIN_LEAD_MIN * 60000) : 0;

      if (nowMs < opens) {
        data.notice = 'Check-in opens an hour before your start time.';
      } else {
        r.setValue('reservation_status', 'checked_in');
        r.work_notes = 'Reservation checked in by ' + gs.getUserDisplayName();
        r.update();
      }
    }
  }

  // The soonest reservation that hasn't finished yet.
  var gr = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  gr.addQuery('reserved_for', gs.getUserID());
  gr.addQuery('reservation_status', 'IN', 'pending_check_in,checked_in');
  gr.orderBy('work_start');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var s = parts(gr.getDisplayValue('work_start'));
    var e = parts(gr.getDisplayValue('work_end'));
    var status = gr.getValue('reservation_status');

    data.res = {
      sysId:       gr.getUniqueValue(),
      number:      gr.getValue('number'),
      workspace:   gr.getDisplayValue('workspace'),
      location:    gr.getDisplayValue('location'),
      statusLabel: gr.getDisplayValue('reservation_status'),
      tint:        status === 'checked_in' ? 'free' : 'held',
      startWeekday: s.weekday,
      startDay:     s.day,
      startMonth:   s.month,
      startTime:    s.time,
      endTime:      e.time,
      endDay:       e.day,
      endMonth:     e.month,
      multiDay:     s.day !== e.day,
      canCheckIn:   status === 'pending_check_in',
      canCheckOut:  status === 'checked_in'
    };
  }

})();
